"""
ivw_orchestrator.py - Orchestriert den IVW-Prozess aus eSuite, SAP und Erlösen.

Fachlicher Hintergrund
----------------------
Die IVW-Meldung eines Titels setzt sich aus drei Datenquellen zusammen:

1. **eSuite-Fulfilments**: Wer hat tatsächlich eine Zeitung bekommen?
   Kommen aus unserem Auftragssystem. Basis für die Zählung einzelner
   Leser-Beziehungen (Verkauf, Verbreitung).

2. **SAP-Auflagen**: Welche zusätzlichen Exemplare wurden gedruckt
   (Werbestücke, Archive) oder zurückgegeben (Remissionen)? Diese
   Zahlen betreffen nur Print und werden nicht über eSuite erfasst.

3. **Erlöse** (optional): Rechnungsbeträge und Gutschriften pro Produkt
   und Rhythmus, zur Plausibilisierung und für Umsatzauswertungen.

Die eSuite-Fulfilments werden bereits beim Dateiimport fachlich angereichert.
Die verbindliche Tagesberechnung erfolgt in SQLMesh. Dieser Orchestrator liest
nur noch die SQLMesh-Tagesdaten und liefert entweder den Tagesexport oder den
bestehenden Gesamtreport fuer den angeforderten Zeitraum.

Die eigentlichen Berechnungen sind in den Service-Modulen gekapselt:
- ivw_esuite_service (SQLMesh-Tagesdaten fuer den Export)
- ivw_sap_service    (SAP-Parser und SAP-Ansicht fuer den Gesamtreport)
- revenue.erloese    (Erloesaufteilung fuer den Gesamtreport)

Verwendung
----------
    from core_services.ivw import get_ivw_data
    get_ivw_data(...) -> pd.DataFrame
"""

import logging
import math
from typing import Literal

import pandas as pd

from ..db.client import connect_to_db
from ..revenue import erloese_final_aggregated_kalendertage
from .ivw_esuite_service import (
    _create_daterange_aggregation,
    _load_et_calendar_counts,
    _prepare_filters,
    load_ivw_daily_from_sqlmesh,
)
from .ivw_sap_service import _create_sap_view

logger = logging.getLogger(__name__)


def _integrate_sap_data(
    gesamt_agg: pd.DataFrame, start_date: str, end_date: str, art_in: str, welt_in: str
) -> pd.DataFrame:
    """Hängt die SAP-Zeilen (Print-Auflagen, Remissionen) an die Gesamt-Auswertung an.

    Die SAP-Zeilen haben exakt dasselbe Spaltenschema wie die
    eSuite-Auswertung; sie werden einfach unter die eSuite-Zeilen gehängt
    (concat). Die Unterscheidung der Herkunft geschieht über die Spalte
    "Quelle" (Werte "eSuite" oder "SAP").

    Fehlt eine erwartete Spalte in den SAP-Daten, wird eine Exception
    geworfen - ein inkomplettes Schema würde zu falsch ausgerichteten
    Zahlen im report führen.
    """
    logger.info("Integriere SAP-Daten in die Gesamt-Aggregation...")
    sap_df = _create_sap_view(start_date, end_date, art_in, welt_in)

    if sap_df is not None and not sap_df.empty:
        expected_base = [
            "Art",
            "PVA",
            "Gesamt_PVA",
            "Bezeichnung",
            "Welt",
            "Objekt",
            "IVWKategorie",
            "Meldekategorie",
            "Verkauf",
            "Verbreitung",
            "Druckauflage",
            "Erscheinung",
            "ANZAHL_ET",
            "Gesamtmenge",
            "DS",
            "Quelle",
            "Zeitraum_von",
            "Zeitraum_bis",
        ]

        missing = [c for c in expected_base if c not in sap_df.columns]
        if missing:
            logger.error(f"SAP-View fehlt erwartete Basis-Spalten: {missing}")
            raise ValueError(f"SAP-View fehlt erwartete Basis-Spalten: {', '.join(missing)}")

        for col in ["ANZAHL_ET", "Gesamtmenge", "DS"]:
            if col in sap_df.columns:
                sap_df[col] = pd.to_numeric(sap_df[col], errors="coerce")
        sap_df["DS"] = sap_df["DS"].map(
            lambda value: math.copysign(math.floor(abs(value) + 0.5), value) if pd.notna(value) else value
        )

        sap_df = sap_df[gesamt_agg.columns]
        before = len(gesamt_agg)
        gesamt_agg = pd.concat([gesamt_agg, sap_df], ignore_index=True)
        logger.info(f"SAP-Daten angehängt: {len(gesamt_agg) - before} Zeilen hinzugefügt.")
    else:
        logger.info("Keine SAP-Daten gefunden für den Zeitraum.")

    return gesamt_agg


def _integrate_erloese_data(gesamt_agg: pd.DataFrame, log_level: str, start_date: str, end_date: str) -> pd.DataFrame:
    """Verknüpft die Erlös-Summen mit der Auflagen-Auswertung.

    Gematcht wird über die gemeinsamen Schlüssel:
        Art, PVA, Bezeichnung, Welt, Objekt, IVWKategorie, Erscheinung

    Für jede Gruppe werden die vier Erlös-Spalten angehängt
    (Forderung_brutto/netto, Gutschrift_brutto/netto). Gruppen ohne
    passende Erlös-Zeile bekommen 0 - ein leerer Eintrag würde in
    Excel Rechenfehler verursachen.
    """
    logger.info("Lade Erlöse-Daten...")
    erloese = erloese_final_aggregated_kalendertage(log_level, start_date, end_date)

    if not erloese.empty:
        gesamt_agg = gesamt_agg.merge(
            erloese, on=["Art", "PVA", "Bezeichnung", "Welt", "Objekt", "IVWKategorie", "Erscheinung"], how="left"
        )
        erloes_cols = ["Forderung_brutto", "Forderung_netto", "Gutschrift_brutto", "Gutschrift_netto"]
        for col in erloes_cols:
            if col in gesamt_agg.columns:
                gesamt_agg[col] = gesamt_agg[col].fillna(0)

        # SAP-Zeilen (Werbestücke, Remissionen etc.) sind reine Auflagenzahlen ohne Umsatz.
        if "Quelle" in gesamt_agg.columns:
            sap_mask = gesamt_agg["Quelle"] == "SAP"
            for col in erloes_cols:
                if col in gesamt_agg.columns:
                    gesamt_agg.loc[sap_mask, col] = 0

        logger.info(f"Erlöse erfolgreich integriert: {len(gesamt_agg)} Zeilen mit Erlösdaten.")
    else:
        logger.warning("Keine Erlöse-Daten gefunden!")

    return gesamt_agg


def _empty_ivw_result(result_type: str) -> pd.DataFrame | dict[str, pd.DataFrame]:
    """Liefert einen leeren Rueckgabewert im angeforderten Ergebnisformat."""
    if result_type == "beides":
        return {"tagesdaten": pd.DataFrame(), "zeitraum": pd.DataFrame()}
    return pd.DataFrame()


def get_ivw_data(
    start_date: str,
    end_date: str,
    art_filter: str,
    welt_filter: str,
    result_type: Literal["tagesdaten", "zeitraum", "beides"] = "beides",
    exp_path: str = "",
    log_level: str = "INFO",
    create_erloese: bool = False,
    sap_data: bool = False,
) -> pd.DataFrame | dict[str, pd.DataFrame]:
    """Erzeugt IVW-Tages- und Zeitraumdaten fuer einen Zeitraum.

    Die Fulfilment-Mengen stammen ausschliesslich aus dem SQLMesh-Modell
    ``dbm_mart.ivw_fulfillment_daily``. Die eSuite-CSV-Daten werden bereits
    beim Import fachlich angereichert; die bisherige Python-Aufbereitung aus
    ``tb_ivw_grundlage`` wird hier nicht mehr verwendet.

    Args:
        start_date: Startdatum des Auswertungszeitraums (``YYYY-MM-DD``).
        end_date: Enddatum des Auswertungszeitraums (``YYYY-MM-DD``).
        art_filter: Komma-getrennte Ausgabearten, z. B. ``Print,ePaper``.
        welt_filter: Komma-getrennte Welten, z. B. ``MS,OWL``.
        result_type: ``beides`` (Standard) liefert Tages- und Gesamtexport
            als Dictionary. ``tagesdaten`` oder ``zeitraum`` liefern weiterhin
            jeweils nur den angeforderten DataFrame.
        exp_path: Weiterhin aus Kompatibilitaetsgruenden vorhandener
            Exportpfad; der DataFrame wird vom Aufrufer geschrieben.
        log_level: Log-Level fuer die Auswertung.
        create_erloese: Ergaenzt Erloesspalten im Gesamtexport.
        sap_data: Ergaenzt SAP-Auflagenzeilen im Gesamtexport.

    Returns:
        Bei ``result_type="beides"`` ein Dictionary mit ``tagesdaten`` und
        ``zeitraum``. Bei den expliziten Ergebnisarten jeweils den passenden
        DataFrame. Der Gesamtexport behaelt sein bestehendes Spaltenschema.
    """
    connection = None
    cursor = None

    try:
        logger.setLevel(getattr(logging, log_level.upper(), logging.INFO))

        connection = connect_to_db()
        if not connection:
            logger.error("Keine Datenbankverbindung hergestellt!")
            return _empty_ivw_result(result_type)

        cursor = connection.cursor(dictionary=True)

        art_in, welt_in = _prepare_filters(art_filter, welt_filter)

        daily = load_ivw_daily_from_sqlmesh(
            cursor,
            art_in,
            welt_in,
            start_date,
            end_date,
        )
        if daily.empty:
            logger.warning("Keine IVW-Tagesdaten gefunden!")
            return _empty_ivw_result(result_type)

        if result_type not in {"tagesdaten", "zeitraum", "beides"}:
            raise ValueError("result_type muss 'tagesdaten', 'zeitraum' oder 'beides' sein.")
        if result_type == "tagesdaten":
            logger.info("Abgeschlossen (tagesdaten): %d Zeilen.", len(daily))
            return daily

        et_counts = _load_et_calendar_counts(cursor, start_date, end_date)
        komplett = _create_daterange_aggregation(daily.copy(), start_date, end_date, et_counts)

        if sap_data and "Print" in art_in:
            komplett = _integrate_sap_data(komplett, start_date, end_date, art_in, welt_in)

        if create_erloese:
            komplett = _integrate_erloese_data(komplett, log_level, start_date, end_date)
        else:
            logger.info("Erloese-Berechnung uebersprungen (create_erloese=False).")

        logger.info("Abgeschlossen (zeitraum): %d Zeilen.", len(komplett))
        if result_type == "zeitraum":
            return komplett
        logger.info("Abgeschlossen (beides): %d Tages- und %d Gesamtzeilen.", len(daily), len(komplett))
        return {"tagesdaten": daily, "zeitraum": komplett}

    except Exception as e:
        logger.error(f"Fehler beim Ausführen der IVW-Abfrage: {e}", exc_info=True)
        return _empty_ivw_result(result_type)

    finally:
        if cursor:
            cursor.close()
        if connection:
            connection.close()
